/* Offline interaction check: execute the actual page script against a small DOM
 * fixture generated by the real template test. No browser or network is used. */
const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const path = require('node:path');
const rootDir = path.resolve(__dirname, '../../..');
const html = fs.readFileSync(path.join(rootDir, '.artifacts/customer-network-simulation-preview.html'), 'utf8');
const payload = html.match(/<script id="SimulationPayload" type="application\/json">([\s\S]*?)<\/script>/)[1];
let checks = 0;
function check(test, label) { assert.ok(test, label); checks++; }
class Item {
    constructor(tag) { this.tag = tag; this.dataset = {}; this.children = []; this.events = {}; this.attrs = {}; this.value = ''; this.textContent = ''; this.classes = new Set(); this.classList = {toggle: (name, on) => on ? this.classes.add(name) : this.classes.delete(name)}; }
    setAttribute(key, value) { this.attrs[key] = String(value); if (key.startsWith('data-')) this.dataset[key.slice(5)] = String(value); }
    appendChild(child) { this.children.push(child); return child; }
    append(...children) { this.children.push(...children); }
    replaceChildren(...children) { this.children = children; if (this.tag === 'select') this.value = ''; }
    add(option) { this.children.push(option); }
    addEventListener(name, fn) { (this.events[name] ||= []).push(fn); }
    emit(name, event = {}) { for (const fn of this.events[name] || []) fn({target: this, ...event}); }
    querySelectorAll(selector) { return this.children.flatMap(child => [child, ...child.querySelectorAll(selector)]).filter(child => selector === '[data-node]' ? child.dataset.node : selector === '[data-device]' ? child.dataset.device : false); }
    getBoundingClientRect() { return {width: 960, height: 420}; }
    closest() { return null; }
    setPointerCapture() {}
}
const items = new Map();
function add(id, tag = 'div') { const item = new Item(tag); items.set(id, item); return item; }
const root = add('NetworkSimulation'), form = add('SimulationForm', 'form');
form.action = 'http://preview.invalid/customer.pl';
const submit = new Item('button'); form.querySelector = () => submit;
add('SimulationPayload', 'script').textContent = payload;
for (const id of ['SimulationGraph','SimulationGraphViewport','SimulationInspector','SimulationEmpty','SimulationProgress','SimulationZoomIn','SimulationZoomOut','SimulationReset']) add(id);
for (const side of ['Source','Destination']) {
    for (const field of ['Application','System','Endpoint']) add(side + field, 'select');
}
const protocol = add('SimulationProtocol', 'select'); protocol.value = 'tcp';
const port = add('SimulationPort', 'input'); port.value = '443';
for (const id of ['101','201','102']) {const button = new Item('button');button.dataset.device=id;root.appendChild(button);}
const document = {readyState: 'complete', getElementById: id => items.get(id), createElementNS: (_, tag) => new Item(tag), createElement: tag => new Item(tag)};
const sandbox = {document, window: {location: {href: form.action}}, URL, Option: class extends Item {constructor(label, value) {super('option');this.textContent=label;this.value=value;}}, console,
    fetch: () => {throw new Error('Unexpected browser network call');}};
vm.runInNewContext(fs.readFileSync(path.join(rootDir, 'var/httpd/htdocs/js/TESSERA.Customer.NetworkSimulation.js'), 'utf8'), sandbox);
const get = id => items.get(id);
const viewport = get('SimulationGraphViewport');
const graphNodes = () => viewport.children.filter(item => item.dataset.node);
const graphEdges = () => viewport.children.filter(item => item.tag === 'path');
check(get('SourceApplication').value === '100', 'source application restored');
check(get('SourceSystem').value === '101', 'source system restored');
check(get('SourceEndpoint').value === '101@0', 'source address restored');
check(get('DestinationEndpoint').value === '102@0', 'destination address restored');
check(graphNodes().length === 3 && graphEdges().length === 2, 'authorized result draws three nodes and two evidence edges');
root.children.find(item => item.dataset.device === '201').emit('click');
check(get('SimulationInspector').children[0].textContent === 'Firewall', 'path table selects the CMDB device');
const link = get('SimulationInspector').children.find(item => item.tag === 'a');
check(link.href.includes('ConfigItemID=201') && !link.href.includes('30000000'), 'device click links to caller CMDB identifier');
let prevented = false; graphNodes()[0].emit('keydown', {key: 'Enter', preventDefault() {prevented = true;}});
check(prevented && get('SimulationInspector').children.length > 0, 'keyboard node selection works');
const initialTransform = viewport.attrs.transform;get('SimulationZoomIn').emit('click');
check(viewport.attrs.transform !== initialTransform, 'zoom control updates the canvas transform');
get('SimulationReset').emit('click');check(viewport.attrs.transform === initialTransform, 'reset restores fit');
get('SourceApplication').value = '200';get('SourceApplication').emit('change');
check(get('SourceSystem').value === '102' && get('SourceEndpoint').value === '102@0', 'single linked system and IP resolve automatically');
check(graphEdges().length === 0, 'changed inputs clear previous path edges');
check(get('SimulationProgress').textContent.includes('saved analysis'), 'old evidence clearly distinguished after input change');
get('SourceApplication').value = '100';get('SourceApplication').emit('change');
check(graphNodes().some(item => item.dataset.node === '101') && graphNodes().some(item => item.dataset.node === '201'), 'application selection immediately shows all its mapped permitted systems');
get('SourceSystem').value = '201';get('SourceSystem').emit('change');
check(get('SourceEndpoint').value === '201@0', 'system selection resolves the corresponding CMDB IP');
check(!get('SourceEndpoint').children.some(item => item.textContent.includes('SECRET-ASSET')), 'unauthorized asset never enters selector');
protocol.value = 'icmp';protocol.emit('change');check(port.disabled && port.value === '', 'ICMP removes destination port');
protocol.value = 'udp';protocol.emit('change');check(!port.disabled && port.required, 'transport protocols require explicit port');
form.emit('submit');check(submit.disabled && get('SimulationProgress').textContent.includes('do not resubmit'), 'submission shows progress and prevents repeat click');
console.log(`${checks} offline UI interaction checks passed.`);
